const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LEVELS=CATALOG.levels;
const CATEGORIES=CATALOG.categories;
Object.assign(QUESTIONS,Object.fromEntries(LEVELS.map(l=>[l.id,l.question])));
const state={screen:'portal',lesson:LEVELS[0].id,step:0,progress:{},loading:true,saveStatus:'',saveError:false,selected:null,feedback:false,saving:false,stream:'biology',modelEngaged:false,bioavailability:.5,halfLife:4,clipStep:0,clipPlaying:false};
let saveQueue=Promise.resolve(),clipTimer;
const ids=LEVELS.map(l=>l.id);
const level=()=>LEVELS.find(l=>l.id===state.lesson);
const done=id=>Boolean(state.progress[id]?.completed);
const countDone=()=>ids.filter(done).length;
const button=(label,action,kind='primary')=>`<button class="button ${kind}" data-action="${action}">${label}</button>`;
function announce(s){$('#announcement').textContent=s;}
function readState(){return {screen:state.screen,lesson:state.lesson,step:state.step,stepName:['Understand','See an example','Try it'][state.step],completedLevels:ids.filter(done),progressLoaded:!state.loading,saveStatus:state.saveStatus,modelEngaged:state.modelEngaged,exposure:{bioavailability:state.bioavailability,halfLife:state.halfLife,...exposureMetrics()}};}
async function request(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw new Error('Progress could not be reached. Your lesson is still available.');}if(!response.ok)throw new Error(data.error||'Progress could not be saved.');return data;}
function applyProgress(data){state.progress=Object.fromEntries((data.lessons||[]).filter(x=>ids.includes(x.lesson)).map(x=>[x.lesson,x]));}
async function loadProgress(){state.loading=true;try{applyProgress(await request('/api/progress'));state.saveStatus='Progress saved to your account';state.saveError=false;}catch(e){state.saveStatus=e.message;state.saveError=true;}state.loading=false;render(false);}
function updateSaveLabel(){const el=$('#save-status');if(el){el.textContent=state.saveStatus;el.classList.toggle('error',state.saveError);}}
function queueStepSave(id,step){state.saveStatus='Saving your place…';state.saveError=false;updateSaveLabel();saveQueue=saveQueue.then(async()=>{try{const data=await request('/api/progress',{lesson:id,step});applyProgress(data);state.saveStatus='Progress saved to your account';state.saveError=false;}catch(e){state.saveStatus=e.message;state.saveError=true;}updateSaveLabel();});return saveQueue;}
function resumeId(){return LEVELS.filter(l=>state.progress[l.id]&&!done(l.id)).sort((a,b)=>(state.progress[b.id].updatedAt||0)-(state.progress[a.id].updatedAt||0))[0]?.id||ids.find(id=>!done(id))||ids[0];}
function overview(){
 const current=resumeId(),completed=countDone(),started=Boolean(state.progress[current]),allDone=completed===ids.length;
 return `<section class="course-intro"><button class="text-button" data-action="portal">← Learning paths</button><h1>Small Molecule</h1><p>From target identification to IND review. One idea at a time.</p></section>
 <section class="level-map" aria-label="Small Molecule level selection">
 <div class="map-titlebar"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>Select a level</span><span class="map-count">${completed} / ${ids.length}</span></div>
 <div class="map-toolbar"><p>${allDone?'All introductory levels completed.':started?'Pick up where you left off.':'Start at 1, or choose a topic.'}</p><button class="map-resume" data-level="${current}">${allDone?'Review':started?'Continue':'Start learning'} <span aria-hidden="true">→</span></button></div>
 <div class="map-categories">${CATEGORIES.map((c,ci)=>{
 const group=LEVELS.filter(l=>l.category===c.id),preview=group.find(l=>l.id===current)||group.find(l=>!done(l.id))||group[0];
 return `<section class="map-category" aria-labelledby="category-${c.id}"><h2 id="category-${c.id}">${c.title}</h2><p class="category-description">${c.description}</p><p class="level-preview" id="preview-${c.id}" aria-live="polite">${group.indexOf(preview)+1}: ${preview.title}</p><div class="numbered-levels">${group.map((l,i)=>{
 const complete=done(l.id),partial=Boolean(state.progress[l.id])&&!complete,status=complete?'Completed':partial?'In progress':'Not started';
 return `<button class="level-box ${complete?'complete':''} ${partial?'in-progress':''} ${l.id===current&&!allDone?'recommended':''}" data-level="${l.id}" data-preview="${l.id}" aria-label="${i+1}. ${escapeHtml(l.title)} — ${status}" title="${escapeHtml(l.title)} · ${status}"><span aria-hidden="true">${complete?'★':i+1}</span></button>`;
 }).join('')}<span class="category-count">${group.filter(l=>done(l.id)).length} / 4</span></div></section>`;
 }).join('')}</div>
 <div class="map-legend"><span><b class="legend-star" aria-hidden="true">★</b> Completed</span><span><i class="legend-progress" aria-hidden="true"></i> In progress</span><span>All levels are open</span></div></section>
 <div class="map-footnote"><p id="save-status" class="save-status ${state.saveError?'error':''}" role="status">${state.loading?'Loading saved progress…':escapeHtml(state.saveStatus)}</p>${state.saveError?button('Retry progress sync','retry','quiet'):''}<p>32 introductory lessons. The order guides learning; real development work overlaps.</p></div>`;
}
function previewLevel(event){const el=event.target.closest('[data-preview]');if(!el)return;const l=LEVELS.find(x=>x.id===el.dataset.preview);if(!l)return;const row=$('#preview-'+l.category);if(row)row.textContent=(LEVELS.filter(x=>x.category===l.category).indexOf(l)+1)+': '+l.title;}
function understanding(){const l=level();return `<p class="eyebrow">THE CONCEPT</p><h2>${l.title}</h2><p>${l.concept}</p>${conceptDiagram()}<div class="takeaway"><span>Keep this idea</span><strong>${l.takeaway}</strong></div>`;}
function boxes(items){return `<div class="concept-diagram">${items.map((x,i)=>`${i?'<b aria-hidden="true">→</b>':''}<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div>`;}
function conceptDiagram(){return boxes(level().diagram);}
function example(){const l=level();return `<p class="eyebrow">WORKED EXAMPLE · INVENTED</p><h2>${l.exampleTitle}</h2><p>${l.example}</p>${state.lesson==='model'?modelExample():state.lesson==='exposure'?exposureExample():simpleExample()}<div class="worked-answer"><span>How to reason through it</span><p>${l.worked}</p></div>`;}
function evidenceExample(){const s=STREAMS.find(x=>x.id===state.stream);return `<div class="example-board"><div class="evidence-tabs" aria-label="Explore an IND workstream">${STREAMS.map(x=>`<button data-stream="${x.id}" aria-pressed="${x.id===s.id}" class="${x.id===s.id?'active':''}">${x.name}</button>`).join('')}</div><div class="evidence-detail" aria-live="polite"><h3>${s.title}</h3><p>${s.text}</p></div></div>`;}
function modelExample(){return `<div class="example-board"><div class="model-pair"><div><span>Human tumor</span><strong>Pathway suppressed</strong><p>Growth slows</p></div><div class="${state.modelEngaged?'engaged':''}"><span>Mouse intestine</span><strong>${state.modelEngaged?'Pathway suppressed':'Pathway remains active'}</strong><p>No injury detected</p></div></div><label class="toggle"><input type="checkbox" id="model-engaged" ${state.modelEngaged?'checked':''}><span>What if the mouse intestinal pathway were also suppressed?</span></label><p class="model-result" aria-live="polite">${state.modelEngaged?'Holding the injury observation constant, the negative finding becomes more informative. Human risk still depends on exposure, duration, assessments, and biological differences.':'The mouse intestine did not experience the relevant pathway inhibition. This leaves the human on-target risk unresolved.'}</p></div>`;}
function exposureMetrics(){const f=state.bioavailability,h=state.halfLife,k=Math.log(2)/h;return {initial:100*f,auc:100*f/k,residual:100*f*Math.exp(-k*24)};}
function exposureChart(){const m=exposureMetrics(),compact=window.matchMedia('(max-width:600px)').matches,width=compact?320:580,scale=compact?10:20;const path=(f,h)=>Array.from({length:97},(_,i)=>`${i?'L':'M'}${58+i/4*scale},${215-100*f*Math.exp(-Math.log(2)/h*i/4)*1.7}`).join(' ');return `<svg viewBox="0 0 ${width} 265" role="img" aria-label="Illustrative concentration over 24 hours. Initial concentration ${m.initial.toFixed(0)} units; AUC ${m.auc.toFixed(0)} unit hours."><text x="58" y="20">${compact?'Concentration (a.u.)':'Concentration (arbitrary units)'}</text>${[0,50,100].map(v=>`<line x1="58" y1="${215-v*1.7}" x2="${58+24*scale}" y2="${215-v*1.7}"/><text x="45" y="${220-v*1.7}" text-anchor="end">${v}</text>`).join('')}<path d="${path(.5,4)}" class="baseline"/><path d="${path(state.bioavailability,state.halfLife)}" class="curve"/>${[0,12,24].map(t=>`<text x="${58+t*scale}" y="240" text-anchor="middle">${t}</text>`).join('')}<text x="${58+12*scale}" y="262" text-anchor="middle">Time (hours)</text></svg>`;}
function exposureExample(){const m=exposureMetrics();return `<div class="example-board exposure-board"><div class="chart-legend"><span>Blue: your settings</span><span>Dashed: 50%, 4 h</span></div><div id="exposure-chart">${exposureChart()}</div><div class="range-row"><label for="bioavailability">Bioavailability <output id="f-value">${Math.round(state.bioavailability*100)}%</output></label><input id="bioavailability" type="range" min="10" max="100" step="5" value="${state.bioavailability*100}"></div><div id="exposure-metrics" class="metrics" aria-live="polite"><span>Initial concentration <strong>${m.initial.toFixed(0)} units</strong></span><span>Total exposure (AUC₀–∞) <strong>${m.auc.toFixed(0)} unit·h</strong></span></div><details class="optional"><summary>Explore half-life and model assumptions</summary><div class="range-row"><label for="half-life">Elimination half-life <output id="h-value">${state.halfLife} h</output></label><input id="half-life" type="range" min="1" max="12" step="1" value="${state.halfLife}"></div><p><code>C(t) = 100 × F × exp(−ln(2) × t / t½)</code></p><p>Fixed dose-to-volume scale; instantaneous systemic entry and first-order elimination. No absorption phase, tissue distribution, metabolites, repeat dosing, or clinical thresholds. Half-life need not equal biological effect duration. AUC₀–∞ = 100 × F × t½ / ln(2).</p><button class="text-button" data-action="reset-exposure">Reset to 50% and 4 hours</button></details></div>`;}
function simpleExample(){return `<div class="worked-steps">${level().exampleSteps.map((x,i)=>`<div><span>${i+1}</span><p><strong>${x[0]}</strong>${x[1]}</p></div>`).join('')}</div>`;}
function practice(){const q=QUESTIONS[state.lesson];const selected=Number.isInteger(state.selected)?q.options[state.selected]:null;return `<p class="eyebrow">YOUR TURN</p><h2>${q.title}</h2><p>${q.prompt}</p><fieldset class="choices"><legend class="sr-only">Choose one answer</legend>${q.options.map((o,i)=>`<label class="choice ${state.selected===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${state.selected===i?'checked':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${o[0]}</span></label>`).join('')}</fieldset><div id="feedback" aria-live="polite">${state.feedback&&selected?`<div class="feedback ${selected[2]?'correct':''}"><strong>${selected[2]?'That conclusion is supported.':'Revisit the reasoning.'}</strong><p>${selected[1]}</p></div>`:''}</div><details class="hint"><summary>Show a hint</summary><p>${q.hint||'Separate the measured observation from the human or safety conclusion. Which extra assumption would that conclusion need?'}</p></details>`;}
function lessonView(){const l=level(),n=LEVELS.filter(x=>x.category===l.category).indexOf(l)+1,correct=state.feedback&&QUESTIONS[l.id].options[state.selected]?.[2];return `<div class="lesson-meta"><button class="text-button" data-action="overview">← All levels</button><span>${CATEGORIES.find(c=>c.id===l.category).title} · ${n} / 4${done(l.id)?' · Completed ✓':''}</span></div><div class="lesson-title"><p>${l.title} · <button class="text-button" data-action="goal">Show goal</button></p></div><ol class="stepper" aria-label="Lesson steps">${['Understand','See an example','Try it'].map((label,i)=>`<li class="${state.step===i?'active':state.step>i?'passed':''}" ${state.step===i?'aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol><section class="lesson-card">${(state.step===0?understanding():state.step===1?example():practice()).replace(/<h2>/g,"<h1>").replace(/<\/h2>/g,"</h1>")}</section><div class="lesson-controls">${state.step?button('← Back','back','quiet'):'<span></span>'}${state.step<2?button(state.step===0?'See an example →':'Your turn →','next'):correct?`<button class="button primary" data-action="complete" ${state.saving?'disabled':''}>${state.saving?'Saving…':'Complete level ✓'}</button>`:`<button class="button primary" data-action="check" ${state.selected===null?'disabled':''}>Check my answer</button>`}</div><p id="save-status" class="save-status ${state.saveError?'error':''}" role="status">${escapeHtml(state.saveStatus)}</p><details class="extra-help"><summary>Sources & optional tools</summary><div class="extra-links">${button('Sources for this level','sources','quiet')}${button('Use with AI','ai','quiet')}${state.lesson==='model'?button('Visual recap','clip','quiet')+button('Design an experiment','experiment','quiet'):''}${state.lesson==='review'?button('Inside the submission','dossier','quiet'):''}</div></details>`;}
function completionView(){const l=level(),index=ids.indexOf(l.id),next=ids[index+1];return `<section class="completion"><span class="completion-mark" aria-hidden="true">✓</span><p class="eyebrow">LEVEL ${LEVELS.filter(x=>x.category===l.category).indexOf(l)+1} COMPLETE</p><h1>${l.title}</h1><p>${l.takeaway}</p><span class="completion-count">${countDone()} of ${ids.length} levels completed</span><div class="completion-actions">${next?`<button class="button primary" data-level="${next}">Next: ${LEVELS[index+1].title} →</button>`:button('Return to all levels','overview')}<button class="text-button" data-action="overview">See your progress</button></div></section>`;}
function portal(){return `<section class="portal"><p class="eyebrow portal-kicker">DISCOVERY → DEVELOPMENT → INVESTIGATIONAL NEW DRUG (IND)</p><h1>Choose your learning path.</h1><p class="portal-lede">From the first biological question to a proposed human study.</p><div class="portal-paths"><button class="path-card available" data-action="overview"><div class="path-card-heading"><div><h2>Small Molecule</h2><p>Target identification, discovery, development, and the Investigational New Drug (IND) application.</p></div><div class="molecule-lockup" aria-label="Small molecule structure"><img src="assets/small-molecule.png" alt="Small molecule structure"></div></div></button><div class="path-card unavailable" aria-label="Biologics, under construction"><h2>Biologics</h2><p class="construction">Under construction</p><span>Coming in a future course update.</span></div></div></section>`;}
function showPortal(){stopClip();if($('#modal').open)$('#modal').close();state.screen='portal';navigateHash('#portal');render();return readState();}
function render(focus=true){document.body.classList.toggle('is-overview',state.screen==='overview');document.body.classList.toggle('is-portal',state.screen==='portal');$('#lesson').innerHTML=state.screen==='portal'?portal():state.screen==='overview'?overview():state.screen==='complete'?completionView():lessonView();document.title=(state.screen==='portal'?'Choose a learning path':state.screen==='overview'?'Small Molecule':level().title)+' · First-In-Class.ai';if(focus){$('#lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function showOverview(){stopClip();if($('#modal').open)$('#modal').close();state.screen='overview';navigateHash('#small-molecule');render();return readState();}
function startLevel(id,step){if(!ids.includes(id))throw new Error('Unknown level');if(step!==undefined&&(!Number.isInteger(step)||step<0||step>2))throw new Error('Step must be 0, 1, or 2');stopClip();if($('#modal').open)$('#modal').close();state.lesson=id;state.step=step??(done(id)?0:state.progress[id]?.step??0);state.selected=null;state.feedback=false;state.screen='lesson';navigateHash(`#small-molecule/${id}/${state.step}`);render();queueStepSave(id,state.step);return readState();}
function moveStep(delta){if(state.screen!=='lesson'||![-1,1].includes(delta))return;state.step=Math.min(2,Math.max(0,state.step+delta));state.selected=null;state.feedback=false;navigateHash(`#small-molecule/${state.lesson}/${state.step}`,true);render();queueStepSave(state.lesson,state.step);}
function checkAnswer(){if(state.selected===null)return;state.feedback=true;render(false);announce(QUESTIONS[state.lesson].options[state.selected][1]);$('#feedback').scrollIntoView({block:'nearest',behavior:'smooth'});}
async function completeLevel(){if(state.saving||state.screen!=='lesson'||state.step!==2||!state.feedback||!QUESTIONS[state.lesson].options[state.selected]?.[2])return;const lesson=state.lesson,answer=state.selected;state.saving=true;render(false);saveQueue=saveQueue.then(async()=>{try{applyProgress(await request('/api/complete',{lesson,answer}));state.saveStatus='Progress saved to your account';state.saveError=false;if(state.screen==='lesson'&&state.lesson===lesson&&state.step===2){state.screen='complete';announce('Level completed and progress saved.');}}catch(e){state.saveStatus=e.message;state.saveError=true;}state.saving=false;render();});return saveQueue;}
function updateExposure(){if(!$('#exposure-chart'))return;const m=exposureMetrics();$('#exposure-chart').innerHTML=exposureChart();$('#f-value').textContent=Math.round(state.bioavailability*100)+'%';$('#h-value').textContent=state.halfLife+' h';$('#exposure-metrics').innerHTML=`<span>Initial concentration <strong>${m.initial.toFixed(0)} units</strong></span><span>Total exposure (AUC₀–∞) <strong>${m.auc.toFixed(0)} unit·h</strong></span>`;}
function setExposure(f,h){if(typeof f!=='number'||!Number.isFinite(f)||f<.1||f>1||Math.abs(f*20-Math.round(f*20))>1e-8)throw new Error('Bioavailability must be 0.10–1.00 in 0.05 increments');if(!Number.isInteger(h)||h<1||h>12)throw new Error('Half-life must be 1–12 hours');state.bioavailability=f;state.halfLife=h;if($('#bioavailability')){$('#bioavailability').value=f*100;$('#half-life').value=h;updateExposure();}return readState();}
function setModel(value){if(typeof value!=='boolean')throw new Error('engaged must be a boolean');state.modelEngaged=value;if(state.lesson==='model'&&state.step===1)render(false);return readState();}
function modal(kicker,html){stopClip();$('#modal').classList.remove?.('welcome-dialog');$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=html;const title=$('#modal-body h2');if(title)title.id='dialog-title';if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
let welcomeOffered=false;
function welcomeSeen(){try{return window.localStorage?.getItem('first-in-class-welcome')==='1';}catch{return false;}}
function welcome(){if(welcomeOffered||welcomeSeen())return;welcomeOffered=true;modal('FIRST-IN-CLASS.AI',`<div class="welcome-copy"><h2>Welcome to the Investigational New Drug (IND)-enabling process.</h2><p>First-In-Class.ai is a guided path for scientists who understand biology and discovery and want to follow a candidate toward a first human study.</p><p>Start with the Small Molecule path. Each level gives you one concept, one worked example, and one short decision exercise. Your progress is saved as you learn.</p><p class="welcome-scope">The sequence is a learning map, not a universal regulatory checklist. Real development work overlaps.</p><button class="welcome-enter" data-action="dismiss-welcome" aria-label="Start learning">✓</button></div>`);$('#modal').classList.add?.('welcome-dialog');}
function dismissWelcome(){try{window.localStorage?.setItem('first-in-class-welcome','1');}catch{}if($('#modal').open)$('#modal').close();}
function sources(){modal('SOURCES & ASSUMPTIONS',`<h2>${level().title}</h2><ul class="source-list">${level().sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.label} ↗</a></li>`).join('')}</ul><p>US FDA pathway. Source check: 14 September 2026. Regulations set requirements; guidance explains agency thinking within its stated context.</p><p>The examples, XYZ1 target, and model values are invented teaching tools. They do not predict human outcomes or define universal study requirements.</p>`);}
function about(){modal('ABOUT THIS COURSE','<h2>For scientists at the handoff.</h2><p>For early R&D scientists who know biology and discovery, and want to understand how a development candidate becomes a clinical-stage drug.</p><p>The approach is mechanistic, experimental, and computational: inspect the assumptions, keep claims tied to evidence, and choose useful next experiments. AI can support this reasoning with source checking.</p><p>The learning flow takes inspiration from <a href="https://github.com/pcottle/learnGitBranching" target="_blank" rel="noopener noreferrer">Learn Git Branching</a>. This prototype has 32 introductory Small Molecule levels, from target identification through IND review. Biologics is under construction. Each has a concept, a worked example, and an exercise. Saved completion means the exercise was finished, not regulatory mastery or IND readiness.</p>');}
function curriculum(){modal('THE LONGER LEARNING PATH','<h2>Build the foundation, then go deeper.</h2><p>The 32 levels cover selected introductory concepts. Future lessons will expand the following topics.</p><ol class="source-list">'+COURSE.map(c=>`<li><strong>${c[0]}</strong><br>${c[1]}</li>`).join('')+'</ol>');}
function dossier(){modal('OPTIONAL REFERENCE','<h2>Where the evidence goes.</h2><p>The electronic common technical document (eCTD) organizes material into five modules.</p><ol><li>Regional administrative material, including the US investigator’s brochure.</li><li>Summaries.</li><li>Quality / CMC.</li><li>Nonclinical study reports.</li><li>Clinical material, including protocols.</li></ol><p>An initial IND need not populate every later-stage section. Technical file acceptance is distinct from scientific review.</p><a href="'+SOURCES[8].url+'" target="_blank" rel="noopener noreferrer">FDA eCTD reference ↗</a>');}
function ai(){const prompt=`Teach me one concept at a time about US IND development. I am an early R&D scientist with experimental and computational biology experience. Current level: ${level().title}. Goal: ${level().goal}\n\nGive one concrete example, then ask one question and wait. Separate observations, inferences, and missing evidence. Verify regulatory claims against current primary FDA or ICH sources, state the scope, and distinguish requirements from guidance. Do not invent FDA decisions or universal study requirements.\n\nCurrent model settings, if relevant: bioavailability ${state.bioavailability}, half-life ${state.halfLife} h, hypothetical mouse intestinal pathway suppression ${state.modelEngaged}. Model values are illustrative and cannot select clinical doses.\n\nSources:\n${level().sources.map(s=>s.url).join('\n')}`;modal('OPTIONAL AI PRACTICE',`<h2>Take this concept to your AI tool.</h2><p>Copy the prompt below into your preferred tool. This website does not connect to a live AI model.</p><label for="ai-prompt">Learning prompt</label><textarea id="ai-prompt" rows="9">${escapeHtml(prompt)}</textarea><div class="modal-actions">${button('Copy prompt','copy')}<span id="copy-status" role="status"></span></div>`);}
async function copyPrompt(){try{await navigator.clipboard.writeText($('#ai-prompt').value);$('#copy-status').textContent='Copied.';}catch{$('#ai-prompt').focus();$('#ai-prompt').select();$('#copy-status').textContent='Use your keyboard to copy the selected text.';}}
function experiment(){modal('OPTIONAL EXPERIMENT DESIGN',`<h2>Address the missing condition.</h2><label for="experiment-note">What model, measurements, and decision would you propose?</label><textarea id="experiment-note" rows="4">${escapeHtml(state.experimentNote||'')}</textarea><p class="fine-print">This optional draft stays in this page session; it is not sent to AI.</p><details><summary>Compare with a worked answer</summary><p>Use a justified model of normal human intestinal function where the drug engages XYZ1. Measure pathway suppression, exposure, and function or injury over time. Interpret a negative finding with assay sensitivity, duration, and model limitations.</p><p>Human intestinal organoids could contribute evidence, but one assay is not a complete safety package.</p></details>`);}
function stopClip(){clearTimeout(clipTimer);state.clipPlaying=false;}
function clip(){state.clipStep=0;modal('55-SECOND VISUAL RECAP · CAPTIONED, NO AUDIO','<h2>Watch the evidence split.</h2><div id="clip-stage"></div><div class="clip-controls">'+button('← Back','clip-prev','quiet')+'<button class="button primary" data-action="clip-play" id="clip-play">Play</button>'+button('Next →','clip-next','quiet')+'</div><details><summary>Read the transcript</summary>'+CLIP.map(c=>`<p>${c[1]}</p>`).join('')+'</details>');drawClip();}
function drawClip(){const c=CLIP[state.clipStep];$('#clip-stage').innerHTML=`<div class="clip-art"><span>${state.clipStep+1} / 6</span><strong>${c[2]}</strong><small>${c[3]}</small></div><p>${c[1]}</p>`;$('#clip-play').textContent=state.clipPlaying?'Pause':state.clipStep===5?'Replay':'Play';$('[data-action="clip-prev"]').disabled=state.clipStep===0;$('[data-action="clip-next"]').disabled=state.clipStep===5;}
function scheduleClip(){clipTimer=setTimeout(()=>{if(!state.clipPlaying)return;if(state.clipStep===5){stopClip();drawClip();return;}state.clipStep++;drawClip();scheduleClip();},CLIP[state.clipStep][4]*1000);}
function playClip(){if(state.clipPlaying){stopClip();drawClip();return;}if(state.clipStep===5)state.clipStep=0;state.clipPlaying=true;drawClip();scheduleClip();}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#lesson').focus();return;}const l=e.target.closest('[data-level]');if(l){startLevel(l.dataset.level);return;}const stream=e.target.closest('[data-stream]');if(stream){state.stream=stream.dataset.stream;render(false);return;}const b=e.target.closest('[data-action]');if(!b)return;const actions={portal:showPortal,'dismiss-welcome':dismissWelcome,goal:()=>modal("YOUR GOAL",`<h2>${level().title}</h2><p>${level().goal}</p>`),overview:showOverview,back:()=>moveStep(-1),next:()=>moveStep(1),check:checkAnswer,complete:completeLevel,retry:loadProgress,sources,about,curriculum,dossier,ai,copy:copyPrompt,experiment,clip,'reset-exposure':()=>setExposure(.5,4),'clip-play':playClip,'clip-prev':()=>{stopClip();state.clipStep=Math.max(0,state.clipStep-1);drawClip();},'clip-next':()=>{stopClip();state.clipStep=Math.min(5,state.clipStep+1);drawClip();}};actions[b.dataset.action]?.();});
document.addEventListener('change',e=>{if(e.target.name==='answer'){state.selected=Number(e.target.value);state.feedback=false;render(false);$(`input[name="answer"][value="${state.selected}"]`).focus({preventScroll:true});}if(e.target.id==='model-engaged'){setModel(e.target.checked);$('#model-engaged').focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='bioavailability')setExposure(Number(e.target.value)/100,state.halfLife);if(e.target.id==='half-life')setExposure(state.bioavailability,Number(e.target.value));if(e.target.id==='experiment-note')state.experimentNote=e.target.value;});
$('#close-modal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('close',stopClip);
let applyingRoute=false;
function navigateHash(hash,replace=false){if(applyingRoute||location.hash===hash)return;history[replace?'replaceState':'pushState'](null,'',hash);}
function applyRoute(){
 applyingRoute=true;
 try{
  const parts=location.hash.slice(1).split('/');
  if(!parts[0]||parts[0]==='portal')showPortal();
  else if(['overview','small-molecule'].includes(parts[0])&&!parts[1])showOverview();
  else {const id=parts[0]==='small-molecule'?parts[1]:parts[0],raw=parts[0]==='small-molecule'?parts[2]:parts[1],step=raw===undefined?undefined:Number(raw);if(ids.includes(id)&& (step===undefined||(Number.isInteger(step)&&step>=0&&step<=2)))startLevel(id,step);else showPortal();}
 }finally{applyingRoute=false;}
}
window.addEventListener('hashchange',applyRoute);
document.addEventListener('pointerover',previewLevel);
document.addEventListener('focusin',previewLevel);
window.matchMedia('(max-width:600px)').addEventListener('change',updateExposure);
async function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const schema=(properties,required=[])=>({type:'object',properties,required,additionalProperties:false});const validate=(input,keys)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!keys.includes(k)))throw new Error('Invalid tool input');};const definitions=[{name:'read_learning_state',description:'Read current level, lesson step, saved completion, and model settings.',inputSchema:schema({}),annotations:{readOnlyHint:true},execute(input){validate(input,[]);return readState();}},{name:'navigate_learning_lesson',description:'Open the overview or a level. Navigation does not complete an exercise.',inputSchema:schema({lesson:{type:'string',enum:['portal','overview','small-molecule',...ids]},step:{type:'integer',minimum:0,maximum:2}},['lesson']),execute(input){validate(input,['lesson','step']);if(input.step!==undefined&&(!Number.isInteger(input.step)||input.step<0||input.step>2))throw new Error('Invalid step');if(input.lesson==='portal')return showPortal();if(['overview','small-molecule'].includes(input.lesson))return showOverview();return startLevel(input.lesson,input.step);}},{name:'configure_model_condition',description:'Set hypothetical mouse intestinal pathway suppression and open its worked example.',inputSchema:schema({engaged:{type:'boolean'}},['engaged']),execute(input){validate(input,['engaged']);setModel(input.engaged);return startLevel('model',1);}},{name:'configure_exposure_model',description:'Configure the illustrative PK model and open its worked example. Does not select clinical doses.',inputSchema:schema({bioavailability:{type:'number',minimum:.1,maximum:1,multipleOf:.05},halfLife:{type:'integer',minimum:1,maximum:12}},['bioavailability','halfLife']),execute(input){validate(input,['bioavailability','halfLife']);setExposure(input.bioavailability,input.halfLife);return startLevel('exposure',1);}}];for(const t of definitions)try{await context.registerTool({...t,annotations:{readOnlyHint:false,untrustedContentHint:false,...t.annotations}},{signal:lifecycle.signal});}catch{console.warn('Optional learning tool unavailable.');}}
render(false);const ready=loadProgress().then(()=>{applyRoute();welcome();});registerAgentTools();
